#include "stm32f4xx_hal.h"
#include "stm32469i_discovery.h"
#include "stm32469i_discovery_lcd.h"
#include "stm32469i_discovery_sdram.h"
#include "logo_ptit.h"

static void SystemClock_Config(void);
static inline uint32_t rgb565_to_argb8888(uint16_t c);
static void DrawLogo(uint32_t x0, uint32_t y0);

int main(void)
{
  /* 1. Khởi tạo HAL */
  HAL_Init();

  /* 2. Cấu hình xung nhịp hệ thống 180 MHz từ thạch anh ngoài HSE 8 MHz */
  SystemClock_Config();

  /* 3. Khởi tạo các LED trạng thái trên bo */
  BSP_LED_Init(LED1);
  BSP_LED_Init(LED2);
  BSP_LED_Init(LED3);
  BSP_LED_Init(LED4);

  /* Bật LED xanh báo hiệu đã khởi động */
  BSP_LED_On(LED1);

  /* 4. Khởi tạo màn hình LCD qua DSI/LTDC (mặc định chiều ngang landscape 800x480) */
  uint8_t lcd_status = BSP_LCD_Init();
  if (lcd_status != LCD_OK)
  {
    /* Báo lỗi qua LED đỏ nếu LCD khởi tạo thất bại */
    BSP_LED_On(LED3);
    while (1)
    {
      BSP_LED_Toggle(LED3);
      HAL_Delay(200);
    }
  }

  /* 5. Khởi tạo lớp hiển thị mặc định tại vùng nhớ SDRAM */
  BSP_LCD_LayerDefaultInit(LTDC_ACTIVE_LAYER_BACKGROUND, LCD_FB_START_ADDRESS);
  BSP_LCD_SelectLayer(LTDC_ACTIVE_LAYER_BACKGROUND);

  /* Bật hiển thị màn hình */
  BSP_LCD_DisplayOn();

  /* Xoá toàn bộ màn hình về màu nền trắng */
  BSP_LCD_Clear(LCD_COLOR_WHITE);

  /* Kích thước màn hình: 800 x 480 */
  uint32_t lcd_w = BSP_LCD_GetXSize();
  uint32_t lcd_h = BSP_LCD_GetYSize();

  /* 6. Vẽ Logo PTIT (240x240) ra giữa màn hình */
  uint32_t logo_x = (lcd_w > LOGO_PTIT_WIDTH) ? ((lcd_w - LOGO_PTIT_WIDTH) / 2) : 0;
  uint32_t logo_y = 30; /* Đặt logo ở phía trên giữa để chừa chỗ cho chữ bên dưới */
  DrawLogo(logo_x, logo_y);

  /* 7. Hiển thị 4 dòng chữ thông tin dự án */
  BSP_LCD_SetBackColor(LCD_COLOR_WHITE);
  BSP_LCD_SetTextColor(LCD_COLOR_DARKBLUE);
  BSP_LCD_SetFont(&Font20);

  /* Dòng 1: Tiêu đề hệ thống */
  BSP_LCD_DisplayStringAt(0, 290, (uint8_t *)"EIDE v3 - IDE nhung co tac tu dong tac gia", CENTER_MODE);

  BSP_LCD_SetTextColor(LCD_COLOR_BLACK);
  BSP_LCD_SetFont(&Font16);

  /* Dòng 2: Tác giả học viên */
  BSP_LCD_DisplayStringAt(0, 330, (uint8_t *)"Hoc vien: Vu Tri Cong", CENTER_MODE);

  /* Dòng 3: Giảng viên hướng dẫn */
  BSP_LCD_DisplayStringAt(0, 360, (uint8_t *)"Giang vien huong dan: TS. Nguyen Trung Hieu", CENTER_MODE);

  BSP_LCD_SetTextColor(LCD_COLOR_RED);
  /* Dòng 4: Tên Học viện */
  BSP_LCD_DisplayStringAt(0, 400, (uint8_t *)"Hoc vien Cong nghe Buu chinh Vien thong", CENTER_MODE);

  /* Báo hiệu vẽ xong thành công qua LED xanh dương */
  BSP_LCD_SetTextColor(LCD_COLOR_GREEN);
  BSP_LED_On(LED4);

  /* Vòng lặp nháy nhẹ LED1 báo chip hoạt động bình thường */
  while (1)
  {
    BSP_LED_Toggle(LED1);
    HAL_Delay(1000);
  }
}

/**
 * @brief Chuyển đổi mã màu 16-bit RGB565 sang 32-bit ARGB8888
 */
static inline uint32_t rgb565_to_argb8888(uint16_t c)
{
  uint32_t r = (c >> 11) & 0x1F;
  uint32_t g = (c >> 5) & 0x3F;
  uint32_t b = c & 0x1F;

  r = (r * 255 + 15) / 31;
  g = (g * 255 + 31) / 63;
  b = (b * 255 + 15) / 31;

  return 0xFF000000UL | (r << 16) | (g << 8) | b;
}

/**
 * @brief Vẽ mảng điểm ảnh logo PTIT (240x240) lên màn hình LCD
 */
static void DrawLogo(uint32_t x0, uint32_t y0)
{
  for (uint32_t y = 0; y < LOGO_PTIT_HEIGHT; y++)
  {
    for (uint32_t x = 0; x < LOGO_PTIT_WIDTH; x++)
    {
      uint16_t pixel565 = logo_ptit_data[y * LOGO_PTIT_WIDTH + x];
      BSP_LCD_DrawPixel(x0 + x, y0 + y, rgb565_to_argb8888(pixel565));
    }
  }
}

